/**
 * دالة الحسابات السيكومترية والعمر النمائي لدليل بورتيدج
 */
export function calculatePortagePsychometrics(scores = {}, chronologicalAgeMonths = 48) {
  const domainStats = {
    infant: { id: 'infant', name: 'قسم نمو الرضيع', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#0284c7' },
    socialization: { id: 'socialization', name: 'التنشئة الاجتماعية', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#2563eb' },
    language: { id: 'language', name: 'النمو اللغوي والتواصل', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#0d9488' },
    self_help: { id: 'self_help', name: 'الرعاية الذاتية والاستقلالية', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#ea580c' },
    cognition: { id: 'cognition', name: 'النمو المعرفي والإدراكي', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#7c3aed' },
    motor: { id: 'motor', name: 'النمو الحركي والتناسق', acquiredCount: 0, assistedCount: 0, deficitCount: 0, naCount: 0, assessedItems: 0, totalDomainItems: 0, earnedScore: 0, maxPossibleScore: 0, percentage: 0, developmentalAgeMonths: 0, developmentalAgeText: '', statusLevel: '', severityColor: '#059669' },
  };

  PORTAGE_ITEMS.forEach(it => {
    const dom = it.domainId;
    if (!domainStats[dom]) return;

    domainStats[dom].totalDomainItems += 1;
    const val = scores[it.id];

    if (val !== undefined && val !== null) {
      const numVal = Number(val);
      if (numVal === 1.0) {
        domainStats[dom].acquiredCount += 1;
        domainStats[dom].assessedItems += 1;
        domainStats[dom].earnedScore += 1.0;
        domainStats[dom].maxPossibleScore += 1.0;
      } else if (numVal === 0.5) {
        domainStats[dom].assistedCount += 1;
        domainStats[dom].assessedItems += 1;
        domainStats[dom].earnedScore += 0.5;
        domainStats[dom].maxPossibleScore += 1.0;
      } else if (numVal === 0.0) {
        domainStats[dom].deficitCount += 1;
        domainStats[dom].assessedItems += 1;
        domainStats[dom].maxPossibleScore += 1.0;
      } else if (numVal === -1) {
        domainStats[dom].naCount += 1;
      }
    }
  });

  let totalAcquiredSkills = 0;
  let totalAssessedSkills = 0;
  let totalEarnedScore = 0;
  let totalPossibleScore = 0;
  let sumDevAgeMonths = 0;
  let activeDomainsCount = 0;

  PORTAGE_DOMAINS.forEach(dom => {
    const stat = domainStats[dom.id];
    if (stat.assessedItems > 0 && stat.maxPossibleScore > 0) {
      stat.percentage = Math.round((stat.earnedScore / stat.maxPossibleScore) * 100);
      
      const domainMaxMonths = dom.id === 'infant' ? 12 : 72;
      const devMonths = Math.round((stat.earnedScore / stat.maxPossibleScore) * domainMaxMonths);
      stat.developmentalAgeMonths = devMonths;

      const years = Math.floor(devMonths / 12);
      const months = devMonths % 12;
      stat.developmentalAgeText = years > 0
        ? (years + ' سنة ' + (months > 0 ? ('و ' + months + ' أشهر') : ''))
        : (months + ' أشهر');

      if (stat.percentage >= 80) {
        stat.statusLevel = 'اكتساب نمائي متقدم ومستقر';
        stat.severityColor = '#059669';
      } else if (stat.percentage >= 50) {
        stat.statusLevel = 'في طور الاكتساب (تأخر بسيط إلى متوسط)';
        stat.severityColor = '#d97706';
      } else {
        stat.statusLevel = 'تأخر نمائي حاد يستدعي تدخلاً فردياً';
        stat.severityColor = '#dc2626';
      }

      totalAcquiredSkills += stat.acquiredCount;
      totalAssessedSkills += stat.assessedItems;
      totalEarnedScore += stat.earnedScore;
      totalPossibleScore += stat.maxPossibleScore;

      sumDevAgeMonths += devMonths;
      activeDomainsCount += 1;
    } else {
      stat.developmentalAgeText = 'لم يتم التقييم';
    }
  });

  const overallPercentage = totalPossibleScore > 0
    ? Math.round((totalEarnedScore / totalPossibleScore) * 100)
    : 0;

  const compositeDevAgeMonths = activeDomainsCount > 0
    ? Math.round(sumDevAgeMonths / activeDomainsCount)
    : 0;

  const compYears = Math.floor(compositeDevAgeMonths / 12);
  const compMonths = compositeDevAgeMonths % 12;
  const compositeDevAgeText = compYears > 0
    ? (compYears + ' سنة ' + (compMonths > 0 ? ('و ' + compMonths + ' أشهر') : ''))
    : (compMonths + ' أشهر');

  const safeChronoAge = chronologicalAgeMonths > 0 ? chronologicalAgeMonths : 48;
  const dqScore = Math.round((compositeDevAgeMonths / safeChronoAge) * 100);

  let overallLevel = 'نمو نمطي سليم ومتقدم';
  let overallColor = '#059669';

  if (dqScore < 55 || overallPercentage < 45) {
    overallLevel = 'تأخر نمائي شامل يستوجب خطة تدخل مبكر مكثفة';
    overallColor = '#dc2626';
  } else if (dqScore < 75 || overallPercentage < 70) {
    overallLevel = 'تأخر نمائي بسيط إلى متوسط (بحاجة لبرنامج تأهيل مساند)';
    overallColor = '#d97706';
  } else if (dqScore < 90) {
    overallLevel = 'مستوى نمائي حدي / في طور الاكتساب والمتابعة';
    overallColor = '#0284c7';
  }

  const delayMonths = Math.max(0, safeChronoAge - compositeDevAgeMonths);

  return {
    totalItems: PORTAGE_ITEMS.length,
    totalAssessedSkills,
    totalAcquiredSkills,
    totalEarnedScore,
    totalPossibleScore,
    overallPercentage,
    compositeDevAgeMonths,
    compositeDevAgeText,
    chronologicalAgeMonths: safeChronoAge,
    dqScore,
    delayMonths,
    overallLevel,
    overallColor,
    domainStats,
  };
}
